  "indicator_readings": [
    {
      "indicator": "MM20",
      "reading": "≈27.5",
      "interpretation": "MM20 com leve inclinação ascendente; preço acima — confirma curto prazo mais positivo."
    },
    {
      "indicator": "MM50",
      "reading": "≈28.0",
      "interpretation": "MM50 em declínio e atuando como resistência de médio prazo; precisa ser rompida com volume para confirmar mudança de tendência."
    },
    {
      "indicator": "MM200",
      "reading": "≈29.5",
      "interpretation": "MM200 acima do preço e ainda descendente — tendência de longo prazo permanece baixista."
    },
    {
      "indicator": "EMA9",
      "reading": "≈27.9",
      "interpretation": "EMA9 cruzou acima da EMA21 — sinal de reversão de curtíssimo prazo e incremento de pressão compradora."
    },
    {
      "indicator": "EMA21",
      "reading": "≈27.6",
      "interpretation": "EMA21 começando a inclinar para cima, suportando a leitura de curto prazo favorável."
    },
    {
      "indicator": "MACD",
      "reading": "MACD ≈0.22; sinal ≈0.13; histograma positivo",
      "interpretation": "Crossover recente e histograma em expansão — momentum de alta ganhando força."
    },
    {
      "indicator": "RSI14",
      "reading": "≈62",
      "interpretation": "RSI em ascensão, confirma força do movimento mas ainda longe da zona de sobrecompra (70)."
    },
    {
      "indicator": "Bandas de Bollinger (20,2σ)",
      "reading": "Expansão recente; preço tocou banda superior",
      "interpretation": "Abertura das bandas após contração indica aumento de volatilidade e valida parcial do rompimento; atenção a possíveis pullbacks após toque na banda superior."
    },
    {
      "indicator": "Volume",
      "reading": "Volume do rompimento acima da média recente",
      "interpretation": "Confirmação parcial do movimento de alta. Para maior convicção desejar volumes sustentados em novos topos; volumes de queda anteriores foram mais fortes."
    }
  ]
}
